{-# LANGUAGE OverloadedStrings #-}
{-# OPTIONS_GHC -Wno-unrecognised-pragmas #-}
{-# HLINT ignore "Use camelCase" #-}

module MainApp where

import Miso
    ( component
    , App
    , text
    )
import Miso.Html
    ( div_
    )
import Data.Text (Text)
import qualified Data.ByteString.Base64 as B64
import Data.ByteString ( ByteString, fromStrict )
import Data.Text.Encoding  (encodeUtf8)
import Data.Aeson (decode)

import Types (PostPart, Site(..))
import PostPartRender (render)

base64_encoded_json_example :: Text
-- base64_encoded_json_example = ""
-- base64_encoded_json_example = ""
base64_encoded_json_example = "WwogIHsKICAgICJjb250ZW50cyI6ICI8QmVuIEZyYW5rbGluIEVkaXRpb24iLAogICAgInRhZyI6ICJTaW1wbGVUZXh0IgogIH0KXQo="
-- "

bytestring_json_example :: ByteString
bytestring_json_example =
    case B64.decode (encodeUtf8 base64_encoded_json_example) of
        Left err -> error err
        Right x -> x


all_post_parts :: [ PostPart ]
all_post_parts =
    case decode (fromStrict bytestring_json_example) of
        Just x -> x
        Nothing -> error "PostPart json cannot be decoded!"


app :: App () ()
app = component () (const $ pure ()) $ const $
    div_
        []
        [ text "<Based"
        ]
